/**
 * The `advanced_search` query language.
 *
 * A plain query is just terms. With the flag on, `kind:` and `project:`
 * prefixes narrow the search before it reaches the index, which is why the
 * parser lives on the client too: the dialog has to show the user what it
 * understood before it spends a round trip.
 */
import type { ProjectId } from "@/types/common";

export type SearchSubjectKind = "issue" | "comment" | "project";

const KINDS: readonly SearchSubjectKind[] = ["issue", "comment", "project"];

export interface ParsedSearchQuery {
  /** The free-text remainder, with every recognised token removed. */
  readonly text: string;
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  /** Tokens that looked like syntax but named nothing we know. */
  readonly unknownTokens: readonly string[];
}

export const DEFAULT_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];

/**
 * @param raw      what the user typed
 * @param advanced whether the `advanced_search` flag is on for this org; when
 *                 false the whole string is treated as free text so a colon in
 *                 a title still finds the title.
 */
export function parseSearchQuery(
  raw: string,
  advanced: boolean,
): ParsedSearchQuery {
  if (!advanced) {
    return {
      text: raw.trim(),
      kinds: DEFAULT_SEARCH_KINDS,
      projectId: null,
      unknownTokens: [],
    };
  }

  const terms: string[] = [];
  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: ProjectId | null = null;

  for (const token of raw.split(/\s+/).filter((part) => part.length > 0)) {
    const separator = token.indexOf(":");
    if (separator <= 0) {
      terms.push(token);
      continue;
    }

    const field = token.slice(0, separator).toLowerCase();
    const value = token.slice(separator + 1);
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
      if (KINDS.includes(kind)) kinds.push(kind);
      else unknown.push(token);
    } else if (field === "project") {
      projectId = value as ProjectId;
    } else {
      unknown.push(token);
    }
  }

  return {
    text: terms.join(" "),
    kinds: kinds.length > 0 ? kinds : DEFAULT_SEARCH_KINDS,
    projectId,
    unknownTokens: unknown,
  };
}

/** A one-line explanation of what the parser understood, for the dialog. */
export function describeQuery(parsed: ParsedSearchQuery): string {
  const parts = [`searching ${parsed.kinds.join(", ")}`];
  if (parsed.projectId !== null) parts.push(`in project ${parsed.projectId}`);
  if (parsed.unknownTokens.length > 0) {
    parts.push(`ignoring ${parsed.unknownTokens.join(", ")}`);
  }
  return parts.join(" · ");
}
"use client";

/**
 * Ctrl+K search overlay; advanced syntax requires `advanced_search`.
 *
 * Must call (do not reimplement): isEnabled
 */
import { useEffect, useState } from "react";
import { Dialog } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Spinner } from "@/components/ui/spinner";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useDebouncedValue } from "@/hooks/use-debounced-value";
import { isEnabled } from "@/lib/feature-flags";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchHit } from "@/server/services/search-service";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { ReactElement } from "react";
import { describeQuery, parseSearchQuery } from "./query-syntax";
import { SearchResults } from "./search-results";

export type SearchDialogProps = {
  open: boolean;
  orgId: OrgId;
  flags: FeatureFlagSnapshot;
  onClose: () => void;
  onSearch: (input: SearchQueryInput) => Promise<ActionResult<SearchHit[]>>;
};

const SEARCH_PAGE_SIZE = 20;

export function SearchDialog(props: SearchDialogProps): ReactElement | null {
  const { open, orgId, flags, onClose, onSearch } = props;

  const [raw, setRaw] = useState("");
  // Results are stored together with the query that produced them, so
  // "still searching" is derived rather than a second piece of state that
  // could disagree with the first.
  const [results, setResults] = useState<{
    query: string;
    hits: readonly SearchHit[];
  }>({ query: "", hits: [] });

  const debounced = useDebouncedValue(raw);
  const advanced =
    flags.advanced_search === true ||
    isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });
  const parsed = parseSearchQuery(debounced, advanced);

  const query = parsed.text;
  const pending = query.length > 0 && results.query !== query;

  useEffect(() => {
    if (!open || query.length === 0) return;

    let cancelled = false;

    void onSearch({
      orgId,
      q: query,
      kinds: [...parsed.kinds],
      ...(parsed.projectId !== null ? { projectId: parsed.projectId } : {}),
      limit: SEARCH_PAGE_SIZE,
    }).then((result) => {
      if (cancelled) return;
      setResults({ query, hits: result.ok ? result.data : [] });
    });

    return () => {
      cancelled = true;
    };
    // `parsed` is derived from the debounced string; depending on its parts
    // keeps the effect from re-firing on every keystroke.
  }, [open, orgId, onSearch, query, parsed.kinds, parsed.projectId]);

  if (!open) return null;

  return (
    <Dialog
      open={open}
      title="Search"
      description={
        advanced
          ? "Use kind:issue or project:<id> to narrow the search."
          : undefined
      }
      onClose={onClose}
    >
      <Input
        name="q"
        type="search"
        value={raw}
        placeholder={advanced ? "kind:comment deploy failed" : "Search…"}
        onChange={setRaw}
      />

      {advanced && debounced.length > 0 ? (
        <p className="mt-1 text-xs text-neutral-500">{describeQuery(parsed)}</p>
      ) : null}

      <div className="mt-3">
        {pending ? (
          <Spinner size="sm" label="Searching" />
        ) : (
          <SearchResults
            hits={results.query === query ? results.hits : []}
            query={query}
            onSelect={() => onClose()}
          />
        )}
      </div>
    </Dialog>
  );
}
import { describe, expect, it } from "vitest";
import {
  describeQuery,
  parseSearchQuery,
} from "@/components/domain/search/query-syntax";

describe("query-syntax/parseSearchQuery", () => {
  it("treats everything as free text when the flag is off", () => {
    const parsed = parseSearchQuery("kind:comment deploy", false);
    expect(parsed.text).toBe("kind:comment deploy");
    expect(parsed.kinds).toEqual(["issue"]);
  });

  it("extracts kind tokens when the flag is on", () => {
    const parsed = parseSearchQuery("kind:comment deploy", true);
    expect(parsed.text).toBe("deploy");
    expect(parsed.kinds).toEqual(["comment"]);
  });

  it("accepts the plural and the in: alias", () => {
    expect(parseSearchQuery("in:projects roadmap", true).kinds).toEqual([
      "project",
    ]);
  });

  it("collects several kinds", () => {
    expect(
      parseSearchQuery("kind:issue kind:comment flaky", true).kinds,
    ).toEqual(["issue", "comment"]);
  });

  it("extracts a project filter", () => {
    const parsed = parseSearchQuery("project:prj_7 latency", true);
    expect(parsed.projectId).toBe("prj_7");
    expect(parsed.text).toBe("latency");
  });

  it("reports tokens it did not understand instead of searching for them", () => {
    const parsed = parseSearchQuery("author:ada bug", true);
    expect(parsed.unknownTokens).toEqual(["author:ada"]);
    expect(parsed.text).toBe("bug");
  });

  it("keeps a leading colon as ordinary text", () => {
    expect(parseSearchQuery(":wat", true).text).toBe(":wat");
  });

  it("falls back to the default kind when only syntax was typed", () => {
    expect(parseSearchQuery("project:prj_7", true).kinds).toEqual(["issue"]);
  });
});

describe("query-syntax/describeQuery", () => {
  it("summarises what the parser understood", () => {
    const parsed = parseSearchQuery("kind:comment project:prj_1 nope:x hi", true);
    const description = describeQuery(parsed);
    expect(description).toContain("searching comment");
    expect(description).toContain("in project prj_1");
    expect(description).toContain("ignoring nope:x");
  });
});

